final class TokenVerifier {
    private final String keyPem;          // jwt.key: PEM khoá công khai của IdP
    private final RSAPublicKey publicKey; // parse từ keyPem

    boolean verify(String token) throws Exception {
        SignedJWT jwt = SignedJWT.parse(token);
        JWSAlgorithm alg = jwt.getHeader().getAlgorithm();
        JWSVerifier verifier = JWSAlgorithm.Family.HMAC_SHA.contains(alg)
                ? new MACVerifier(keyPem.getBytes(StandardCharsets.UTF_8)) // nhánh cũ
                : new RSASSAVerifier(publicKey);
        return jwt.verify(verifier)
                && jwt.getJWTClaimsSet().getExpirationTime().after(new Date());
    }
}

