// Ghim thuật toán và nguồn khoá phía server; không đọc alg từ token để chọn cách kiểm
@Bean
JwtDecoder jwtDecoder(@Value("${idp.issuer}") String issuer) {
    NimbusJwtDecoder decoder = NimbusJwtDecoder
            .withIssuerLocation(issuer)              // lấy jwks_uri từ metadata
            .jwsAlgorithm(SignatureAlgorithm.RS256)  // chỉ RS256
            .build();
    decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(
            JwtValidators.createDefaultWithIssuer(issuer),
            new JwtClaimValidator<List<String>>("aud",
                    aud -> aud != null && aud.contains("payment-api"))));
    return decoder;
}

